SELECT COALESCE(SUM(CASE WHEN a.status='PENDING' THEN 1 ELSE 0 END),0) AS attachmentsPending,COALESCE(SUM(CASE WHEN f.revision>f.synced_revision OR f.error IS NOT NULL THEN 1 ELSE 0 END),0) AS derivativesPending FROM metadata_document m JOIN metadata_document v ON v.id=m.parent_id LEFT JOIN metadata_attachment_task a ON a.media_id=m.id LEFT JOIN media_metadata_file f ON f.song_id=m.id WHERE m.entity_type='MEDIA' AND (m.id=? OR v.id=? OR v.parent_id=?)
